function probe(host){
  var r=null;
  try{ r=java.connect('https://'+host+'/',{},9000); }catch(e){ return 'E:'+String(e).slice(0,40); }
  if(r===null||r===undefined) return 'E:无响应';
  var code=0; try{ code=Number(r.code()); }catch(e0){}
  var b=''; try{ b=String(r.body()); }catch(e1){}
  if(b.indexOf('Exception')>-1||b.indexOf('timeout')>-1){
    return 'E:'+b.slice(0,60).split(String.fromCharCode(10)).join(' ');
  }
  if(code!==200) return 'E:HTTP'+code;
  if(b.indexOf('stui-vodlist')<0&&b.indexOf('花都')<0&&b.indexOf('vod')<0) return 'E:内容异常';
  var ct=0; try{ ct=Number(r.callTime()); }catch(e2){}
  return ct;
}
function FQ_fetchLines(){
