  toast('🔗 正在从发布页获取线路：'+ROOT+' ...');
  var BUILTIN='hd.hdys04.com,hd.hdys03.com,hd.hdys02.com,hd.hdzy.org,hd.huadudm.org,hd.huadudm.net,hd.huaduyy.com,hd.huaduys.org,hd.huaduyy.org,hd.hdys.net,hd.hdys0.com';
