  try{ src1=String(java.ajax(ROOT+'js/config.js')); }catch(e){ src1=''; }
  if(badText(src1)){
    try{ src2=String(java.ajax(ROOT)); }catch(e2){ src2=''; }
  }
  var text=(badText(src1)?'':src1)+(badText(src2)?'':src2);
  var hosts={},n=0;
  if(text){
    var re=/"https:\/\/"\s*\+\s*\w+\s*\+\s*"\.([a-zA-Z0-9.-]+)"/g,mm;
    while((mm=re.exec(text))!==null){
      var d=mm[1].toLowerCase();
      if(/hdfby|hdys\.top/.test(d)) continue;
      if(d.length<5||d.length>30) continue;
      if(!hosts['hd.'+d]){ hosts['hd.'+d]=1; n++; }
    }
  }
  var list=[];
  if(n>0){
    for(var k in hosts) list.push(k);
    var srcName=badText(src1)?'发布页首页':'config.js';
    toast('✅ 已从'+srcName+'获取 '+list.length+' 条泛解析线路\n失效线路会在「测试延时」中标✗');
  }else{
    list=BUILTIN.split(',');
    toast('⚠️ 发布页不可达，使用内置 '+list.length+' 条实测线路\n可修改发布页地址重试(4.hdfby.net打不开就换其他字母数字)');
  }
  try{ source.put('hdLines',list.join(',')); }catch(e4){}
  refreshUi();
  return 'ok';
}
function FQ_testDelay(){
  var hs=[];
  try{
    var s=String(source.get('hdLines')||'');
    if(s.indexOf('.')>0) hs=s.split(',');
  }catch(e0){}
  if(hs.length===0){ hs=[MAIN()]; }
  toast('⏱ 正在测试 '+hs.length+' 条线路延时，请稍候...');
  var res=[],best='',bt=900001,okN=0;
  for(var i=0;i<hs.length;i++){
    var r=probe(hs[i]);
    if(typeof r==='number'){
      res.push(hs[i]+':'+r+'ms');
      if(r<bt){ bt=r; best=hs[i]; }
      okN++;
    }else{
      res.push(hs[i]+':✗');
    }
  }
  try{ source.put('hdDelay',res.join('|')); }catch(e1){}
  if(okN>0){
    try{
      source.put('hdBest',best);
      source.put('hdHost',best);
    }catch(e2){}
    toast('✅ 测速完成，已自动切换到最快线路 ⚡'+best+' '+bt+'ms\n'+res.join(' | '));
  }else{
    toast('❌ 全部线路测试失败\n请点「获取路线」更新，或检查网络');
  }
  refreshUi();
  return 'ok';
}
