  var html='';
  try{ html=String(result); }catch(e0){ html=''; }
  if(!html||html.length<200) return [];
  var doc=null;
  try{
    doc=(typeof result!=='undefined'&&result&&typeof result.select==='function')?result:Packages.org.jsoup.Jsoup.parse(html);
  }catch(e){ return []; }
  var uls=doc.select('ul.stui-vodlist');
  if(!uls||uls.size()===0) return [];
  var best=null,bestN=-1;
  for(var i=0;i<uls.size();i++){
    var n=uls.get(i).select('li').size();
    if(n>bestN){ bestN=n; best=uls.get(i); }
  }
  if(!best||bestN<=0){
    var h=String(html);
    if(/([0-9]+)<\/strong>&nbsp;个结果/.test(h)) return [];
    if(h.indexOf('暂无数据')>=0) return [];
    var st=doc.select('span.stats-text');
    var cur=0,tot=0;
    if(st.size()>0){
      var sm=String(st.get(0).text()).replace(/\s+/g,'').match(/第([0-9]+)\/([0-9]+)页/);
      if(sm){ cur=Number(sm[1]); tot=Number(sm[2]); }
    }
    if(cur>0&&tot>0&&cur>=tot) return [];
    var pg='';
    try{ var bm=String(baseUrl).match(/[-]([0-9]+)[-]{3}[.]html/); if(bm) pg=bm[1]; }catch(e2){}
    throw new Error('第'+(pg||'?')+'页返回空页面（站点可能临时限流），请点「重试」');
  }
  var out=[],lis=best.select('li');
  for(var j=0;j<lis.size();j++){
    var li=lis.get(j);
    var a=li.select('h4.title a').first();
    if(a===null) continue;
    var href=String(a.attr('href'));
    var hm=href.match(/^\/voddetail(\d+)\.html$/);
    if(!hm) continue;
    var name=String(a.attr('title')).trim();
    if(!name) name=String(a.text()).trim();
    if(!name) continue;
    var cover='';
    var img=li.select('img').first();
    if(img!==null){
      cover=String(img.attr('data-original')).trim();
      if(!cover) cover=String(img.attr('src')).trim();
      if(cover.indexOf('load.gif')>=0) cover='';
    }
    var cat='',dur='';
    var s1=li.select('span.pic-tag-t').first(); if(s1!==null) cat=String(s1.text()).trim();
    var s2=li.select('span.pic-tag-b').first(); if(s2!==null) dur=String(s2.text()).trim();
    var meta='';
    var s3=li.select('span.text').first(); if(s3!==null) meta=String(s3.text()).trim();
    var bits=[];
    if(cat) bits.push(cat);
    if(dur) bits.push(dur);
    if(meta) bits.push(meta);
    out.push(String(JSON.stringify({n:name,u:'/voddetail'+hm[1]+'.html',c:cover,m:bits.join(' · '),k:cat})));
  }
  return out;
})()

